import React, { useState, useEffect } from 'react';
import { ScanResult, AttendanceType, TimeSlotSettings } from '../types';

interface KioskModeProps {
  onExit: () => void;
  lastScanResult: ScanResult | null;
  unknownTag: string | null;
  settings: TimeSlotSettings;
}

const KioskMode: React.FC<KioskModeProps> = ({ onExit, lastScanResult, unknownTag, settings }) => {
  const [currentTime, setCurrentTime] = useState(new Date());

  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  const getSessionInfo = () => {
    const timeStr = currentTime.getHours().toString().padStart(2, '0') + ':' + currentTime.getMinutes().toString().padStart(2, '0');

    if (timeStr >= settings.amIn.start && timeStr <= settings.amIn.end) 
      return { label: 'Morning Entry', range: `${settings.amIn.start} — ${settings.amIn.end}` };
    if (timeStr >= settings.amOut.start && timeStr <= settings.amOut.end) 
      return { label: 'Morning Exit', range: `${settings.amOut.start} — ${settings.amOut.end}` };
    if (timeStr >= settings.pmIn.start && timeStr <= settings.pmIn.end) 
      return { label: 'Afternoon Entry', range: `${settings.pmIn.start} — ${settings.pmIn.end}` };
    if (timeStr >= settings.pmOut.start && timeStr <= settings.pmOut.end) 
      return { label: 'Afternoon Exit', range: `${settings.pmOut.start} — ${settings.pmOut.end}` };

    return { label: 'Out of Session', range: 'Archiving as Unscheduled' };
  };

  const session = getSessionInfo();

  const getStatusColor = (result: ScanResult) => {
    if (result.isDuplicate) return 'text-amber-600 bg-amber-50 border-amber-100';

    switch (result.type) {
      case 'AM_IN': return 'text-emerald-600 bg-emerald-50 border-emerald-100';
      case 'AM_OUT': return 'text-amber-600 bg-amber-50 border-amber-100';
      case 'PM_IN': return 'text-primary bg-primary/5 border-primary/10';
      case 'PM_OUT': return 'text-accent bg-accent/5 border-accent/10';
      default: return 'text-slate-600 bg-slate-50 border-slate-100';
    }
  };

  return (
    <div className="fixed inset-0 bg-app-bg text-on-surface flex flex-col items-center z-[2000] overflow-hidden select-none">
      {/* Subtle Background Decorative Blur */}
      <div className="absolute inset-0 pointer-events-none opacity-40">
        <div className="absolute top-0 right-0 w-[30vmax] h-[30vmax] bg-white rounded-full blur-[100px] -translate-y-1/2 translate-x-1/2" />
        <div className="absolute bottom-0 left-0 w-[30vmax] h-[30vmax] bg-primary/10 rounded-full blur-[100px] translate-y-1/2 -translate-x-1/2" />
      </div>

      {/* Exit Button */}
      <button 
        onClick={onExit}
        className="absolute top-6 left-6 bg-white/80 backdrop-blur-sm shadow-sm border border-black/5 text-slate-400 hover:text-primary px-5 py-2.5 rounded-full font-bold text-[10px] tracking-widest uppercase transition-all flex items-center gap-2 z-50 group"
      >
        <span className="material-symbols-outlined text-base group-hover:-translate-x-1 transition-transform">arrow_back</span>
        Return
      </button>

      {/* Main Content Area: Responsive Flex Column */}
      <div className="w-full h-full flex flex-col items-center justify-between py-12 px-6 max-w-5xl mx-auto">

        {/* Top Section: Clock & Session */}
        <div className="w-full flex flex-col items-center gap-2 sm:gap-4 z-10 flex-shrink-0 animate-in fade-in slide-in-from-top-4 duration-700">
          <div className="text-[12vh] sm:text-[10vh] font-black text-primary font-mono tracking-tighter tabular-nums leading-none">
            {currentTime.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false })}
          </div>
          <div className="flex items-center justify-center gap-2 px-6 py-2 bg-white/60 backdrop-blur-md rounded-full border border-black/5 shadow-sm">
            <span className="material-symbols-outlined text-slate-400 text-lg leading-none">schedule</span>
            <span className="text-[10px] sm:text-xs font-black text-slate-600 uppercase tracking-widest">{session.label}</span>
            <span className="w-1 h-1 bg-slate-300 rounded-full" />
            <span className="text-[10px] sm:text-xs font-black text-primary/60 uppercase tracking-widest">{session.range}</span>
          </div>
        </div>

        {/* Center Dynamic Content: Constrained to available space */}
        <div className="relative z-10 w-full flex-1 flex flex-col items-center justify-center min-h-0 py-8 overflow-hidden">
          {!lastScanResult && !unknownTag ? (
            <div className="flex flex-col items-center justify-center space-y-8 animate-in fade-in zoom-in duration-700">
              <div className="w-[25vh] h-[25vh] max-w-[250px] max-h-[250px] bg-white/40 rounded-full flex items-center justify-center relative border border-white/20 shadow-xl backdrop-blur-sm">
                <div className="absolute inset-0 bg-primary/10 rounded-full animate-ping opacity-20" />
                <span className="material-symbols-outlined text-[12vh] text-primary/30 leading-none">contactless</span>
              </div>
              <div className="text-center space-y-2">
                <h2 className="text-[6vh] sm:text-[8vh] font-black tracking-tighter text-primary uppercase italic leading-none">TAP CARD</h2>
                <p className="text-[10px] sm:text-xs font-black text-slate-400 tracking-[0.5em] uppercase opacity-50">Awaiting Signal</p>
              </div>
            </div>
          ) : lastScanResult ? (
            <div className="bg-white rounded-[40px] shadow-[0_32px_80px_-16px_rgba(0,0,0,0.15)] p-10 sm:p-14 w-full flex flex-col justify-center text-center space-y-8 animate-in slide-in-from-bottom-20 duration-500 border-t-[12px] border-emerald-500 max-h-full overflow-hidden">
              <div className="flex justify-center">
                <div className={`inline-flex items-center gap-4 px-8 py-3 rounded-full ${getStatusColor(lastScanResult)} font-bold shadow-sm border`}>
                  <span className="material-symbols-outlined text-xl leading-none">
                    {lastScanResult.isDuplicate ? 'history' : 'check_circle'}
                  </span>
                  <span className="text-sm sm:text-lg font-black uppercase italic tracking-wide">
