                  </span>
                </div>
              </div>

              <div className="flex-1 flex flex-col justify-center space-y-4">
                <div className="space-y-2">
                  <h3 className="text-[5vh] sm:text-[7vh] font-black text-primary leading-[1.1] uppercase tracking-tighter break-words px-2">
                    {lastScanResult.learner.firstName}<br/>{lastScanResult.learner.lastName}
                  </h3>
                  <div className="inline-block text-[10px] sm:text-xs font-black text-slate-400 uppercase tracking-widest bg-slate-50 px-6 py-2 rounded-full border border-black/5">
                    {lastScanResult.learner.grade_level} • {lastScanResult.learner.section_name}
                  </div>
                </div>

                <div className="flex items-center justify-center gap-3 text-slate-300 font-bold tracking-widest text-lg sm:text-xl">
                  <span className="material-symbols-outlined text-xl leading-none">schedule</span>
                  {lastScanResult.time}
                </div>
              </div>

              {lastScanResult.isDuplicate && (
                <div className="bg-amber-50 rounded-2xl py-3 px-8 inline-block border border-amber-100 flex-shrink-0">
                  <p className="text-amber-700 text-[10px] font-black uppercase tracking-widest">Duplicate Entry Ignored</p>
                </div>
              )}
            </div>
          ) : (
            <div className="bg-white rounded-[40px] shadow-[0_32px_80px_-16px_rgba(0,0,0,0.15)] p-10 sm:p-14 w-full flex flex-col justify-center text-center space-y-8 animate-in shake duration-500 border-b-[12px] border-accent max-h-full overflow-hidden">
              <div className="w-[15vh] h-[15vh] max-w-[150px] max-h-[150px] bg-accent/5 rounded-full flex items-center justify-center mx-auto border border-accent/10">
                <span className="material-symbols-outlined text-[8vh] text-accent leading-none">warning</span>
              </div>
              <div className="space-y-4 flex-1 flex flex-col justify-center">
                <h3 className="text-[4vh] sm:text-[5vh] font-black text-primary uppercase italic leading-tight">Access Restricted</h3>
                <p className="text-[10px] sm:text-xs font-bold text-slate-400 uppercase tracking-widest font-mono">UID: {unknownTag}</p>
                <div className="h-1 w-20 bg-accent/10 rounded-full mx-auto" />
