export default KioskMode;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { useSerial } from './hooks/useSerial';
import { useLearners } from './hooks/useLearners';
import { useAttendance } from './hooks/useAttendance';
import { useSettings } from './hooks/useSettings';
import { ScanResult, AttendanceType, TimeSlotSettings } from './types';

import Header from './components/Header';
import Footer from './components/Footer';
import KioskMode from './components/KioskMode';
import PairingConsole from './components/PairingConsole';
import LearnerDirectory from './components/LearnerDirectory';
import Terminal from './components/Terminal';
import AttendanceLogs from './components/AttendanceLogs';
import Settings from './components/Settings';

const extractUid = (text: string): string | null => {
  const clean = text.trim().toUpperCase();
  if (clean.includes('READY') || clean.includes('INITIALIZING') || clean.includes('MFRC522')) return null;
  const hexPattern = /[0-9A-F]{2}(?:[\s:-]?[0-9A-F]{2}){3,9}/;
  const match = clean.match(hexPattern);
  if (match) return match[0].replace(/[\s:-]+/g, '');
  return null;
};

const determineAttendanceType = (now: Date, settings: TimeSlotSettings): AttendanceType => {
  const time = now.getHours().toString().padStart(2, '0') + ':' + now.getMinutes().toString().padStart(2, '0');

  if (time >= settings.amIn.start && time <= settings.amIn.end) return 'AM_IN';
  if (time >= settings.amOut.start && time <= settings.amOut.end) return 'AM_OUT';
  if (time >= settings.pmIn.start && time <= settings.pmIn.end) return 'PM_IN';
  if (time >= settings.pmOut.start && time <= settings.pmOut.end) return 'PM_OUT';

  return 'UNSCHEDULED';
};

const App: React.FC = () => {
  const { status, logs, connect, disconnect } = useSerial();
  const { learners, isLoading, isSyncing, fetchedCount, getFiltered } = useLearners();
  const { uidMappings, attendanceLogs, addMapping, logAttendance } = useAttendance();
  const { settings, updateSettings } = useSettings();

  const [currentView, setCurrentView] = useState<'registrar' | 'attendance' | 'settings'>('registrar');
  const [isStandbyMode, setIsStandbyMode] = useState(false);

  const [baudRate, setBaudRate] = useState(() => {
    const saved = localStorage.getItem('last_baud_rate');
    return saved ? parseInt(saved) : 9600;
  });
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedLearnerId, setSelectedLearnerId] = useState<string | null>(null);
  const [activeRfid, setActiveRfid] = useState('');
  const [conflictWarning, setConflictWarning] = useState<string | null>(null);
  const [scanFlash, setScanFlash] = useState(false);

  const [lastScanResult, setLastScanResult] = useState<ScanResult | null>(null);
  const [unknownTag, setUnknownTag] = useState<string | null>(null);

  const lastProcessedId = useRef<string | null>(null);

  useEffect(() => {
    if (logs.length === 0) return;

    const lastLog = logs[logs.length - 1];
    if (!lastLog || lastLog.type !== 'in' || lastLog.id === lastProcessedId.current) return;

    const scannedUid = extractUid(lastLog.text);
    if (!scannedUid) return;

    lastProcessedId.current = lastLog.id;

    if (isStandbyMode) {
      const learner = learners.find(l => {
        const dbUid = l.rfid?.toUpperCase().replace(/[\s:-]+/g, '');
        const localUid = uidMappings[l.id]?.toUpperCase().replace(/[\s:-]+/g, '');
        return dbUid === scannedUid || localUid === scannedUid;
      });

      if (learner) {
        const now = new Date();
        const type = determineAttendanceType(now, settings);

        const todayStr = now.toDateString();
        const isDuplicate = attendanceLogs.some(log => {
          const logDate = new Date(log.timestamp).toDateString();
          return log.learnerId === learner.id && log.type === type && logDate === todayStr;
        });

        if (isDuplicate) {
          setLastScanResult({
            learner, 
            type, 
            uid: scannedUid,
            isDuplicate: true,
            time: now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
          });
        } else {
          logAttendance(learner.id, type);
          setLastScanResult({
            learner, 
            type, 
            uid: scannedUid,
            isDuplicate: false,
            time: now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
          });
        }
        setUnknownTag(null);
      } else {
        setUnknownTag(scannedUid);
        setLastScanResult(null);
      }
    } else {
      setScanFlash(true);
      setActiveRfid(scannedUid);
      setConflictWarning(null);

      const owner = learners.find(l => {
        const dbUid = l.rfid?.toUpperCase().replace(/[\s:-]+/g, '');
        const localUid = uidMappings[l.id]?.toUpperCase().replace(/[\s:-]+/g, '');
        return dbUid === scannedUid || localUid === scannedUid;
      });

      if (owner) {
        setConflictWarning(`Tag assigned to: ${owner.lastName}, ${owner.firstName}`);
      }
      setTimeout(() => setScanFlash(false), 500);
    }
  }, [logs, isStandbyMode, uidMappings, learners, settings, logAttendance, attendanceLogs]);

  useEffect(() => {
    if (lastScanResult || unknownTag) {
      const t = setTimeout(() => { 
        setLastScanResult(null); 
        setUnknownTag(null); 
      }, 5000);
      return () => clearTimeout(t);
    }
  }, [lastScanResult, unknownTag]);

  const handleSaveMapping = () => {
    if (!selectedLearnerId || !activeRfid || conflictWarning) return;
    addMapping(selectedLearnerId, activeRfid);
    setActiveRfid('');
    setSelectedLearnerId(null);
    setConflictWarning(null);
    setScanFlash(true);
    setTimeout(() => setScanFlash(false), 400);
  };

  const filteredLearners = useMemo(() => 
    getFiltered(searchQuery, uidMappings), 
    [searchQuery, learners, uidMappings, getFiltered]
  );

  const selectedLearner = learners.find(l => l.id === selectedLearnerId) || null;

  if (isStandbyMode) {
    return (
      <KioskMode 
        onExit={() => setIsStandbyMode(false)} 
        lastScanResult={lastScanResult} 
        unknownTag={unknownTag} 
        settings={settings}
      />
    );
  }

  return (
    <div className="min-h-screen bg-app-bg text-on-surface flex flex-col font-sans selection:bg-primary-container selection:text-on-primary-container">
      <div className="flex-grow max-w-7xl mx-auto w-full px-4 lg:px-8 py-8 space-y-8">
        <Header 
          status={status} 
          baudRate={baudRate} 
          currentView={currentView}
          onViewChange={setCurrentView}
          onBaudRateChange={(b) => {
            setBaudRate(b);
            localStorage.setItem('last_baud_rate', b.toString());
          }} 
          onConnect={() => connect({ baudRate })} 
          onDisconnect={disconnect} 
          onEnterKiosk={() => setIsStandbyMode(true)} 
        />

        <main className="animate-in fade-in duration-700">
          {currentView === 'registrar' && (
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
              <div className="lg:col-span-4 space-y-6">
                <PairingConsole 
                  activeRfid={activeRfid} 
                  selectedLearner={selectedLearner} 
                  conflictWarning={conflictWarning} 
                  scanFlash={scanFlash} 
                  onSave={handleSaveMapping} 
                />

                <section className="bg-surface rounded-m3-xl p-6 shadow-sm border border-black/5">
                  <div className="flex justify-between items-center mb-4">
                    <h2 className="text-[11px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2">
                      <span className="material-symbols-outlined text-sm">terminal</span>
                      Serial Monitor
                    </h2>
                    <span className={`text-[9px] font-black px-2 py-0.5 rounded ${status === 'connected' ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-100 text-slate-400'}`}>
                      {status.toUpperCase()}
                    </span>
                  </div>
                  <div className="h-64 rounded-m3-lg overflow-hidden bg-surface-variant border border-black/5">
                    <Terminal logs={logs.slice(-100)} />
                  </div>
                </section>
              </div>
              <div className="lg:col-span-8 space-y-6">
                <div className="relative">
                  <span className="material-symbols-outlined absolute left-5 top-1/2 -translate-y-1/2 text-slate-400">search</span>
                  <input 
                    type="text" 
                    placeholder="Search registry..." 
                    value={searchQuery} 
                    onChange={e => setSearchQuery(e.target.value)} 
                    className="w-full bg-surface border border-black/5 rounded-full pl-14 pr-6 py-4 text-base focus:ring-2 focus:ring-primary/20 outline-none transition-all placeholder:text-slate-300 shadow-sm" 
                  />
                </div>
                <LearnerDirectory 
                  learners={filteredLearners} 
                  uidMappings={uidMappings} 
                  selectedId={selectedLearnerId} 
                  onSelect={setSelectedLearnerId} 
                  isLoading={isLoading} 
                  isSearching={searchQuery.trim().length > 0}
                  isSyncing={isSyncing} 
                  fetchedCount={fetchedCount} 
                />
              </div>
            </div>
          )}

          {currentView === 'attendance' && (
            <AttendanceLogs logs={attendanceLogs} learners={learners} />
          )}

          {currentView === 'settings' && (
            <Settings settings={settings} onUpdate={updateSettings} />
          )}
        </main>
      </div>

      <Footer 
        status={status} 
        baudRate={baudRate} 
        assignedCount={Object.keys(uidMappings).length} 
        totalCount={learners.length} 
      />
    </div>
  );
};

export default App;

import { useState, useCallback, useRef, useEffect } from 'react';
import { SerialLog, ConnectionStatus, SerialOptions } from '../types';

export const useSerial = () => {
  const [status, setStatus] = useState<ConnectionStatus>('disconnected');
  const [logs, setLogs] = useState<SerialLog[]>([]);
  const [error, setError] = useState<string | null>(null);

  const readerRef = useRef<ReadableStreamDefaultReader<Uint8Array> | null>(null);
  const portRef = useRef<any>(null);
  const isAutoConnecting = useRef(false);
  const readLoopActive = useRef(false);
  const bufferRef = useRef('');
  const flushTimeoutRef = useRef<number | null>(null);

  const addLog = useCallback((text: string, type: SerialLog['type']) => {
    const newLog: SerialLog = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date(),
      type,
      text
    };
    setLogs(prev => [...prev.slice(-499), newLog]);
  }, []);

  const flushBuffer = useCallback(() => {
    if (bufferRef.current.trim()) {
      addLog(bufferRef.current.trim(), 'in');
      bufferRef.current = '';
    }
    if (flushTimeoutRef.current) {
      window.clearTimeout(flushTimeoutRef.current);
      flushTimeoutRef.current = null;
    }
  }, [addLog]);

  const disconnect = useCallback(async (isHardwareLoss = false) => {
    try {
      flushBuffer();

      if (readerRef.current) {
        await readerRef.current.cancel().catch(() => {});
        readerRef.current = null;
      }

      let timeout = 0;
      while (readLoopActive.current && timeout < 20) {
        await new Promise(r => setTimeout(r, 50));
        timeout++;
      }

      if (portRef.current) {
        try {
          await portRef.current.close().catch(() => {});
        } catch (e) {}
        portRef.current = null;
      }

      setStatus('disconnected');
      if (isHardwareLoss) {
        addLog('Hardware Disconnected: Device link lost.', 'error');
      } else {
        addLog('Disconnected safely.', 'info');
      }
    } catch (e) {
      console.error("Cleanup error:", e);
      setStatus('disconnected');
    }
  }, [addLog, flushBuffer]);

  const startReading = useCallback(async (selectedPort: any) => {
    if (!selectedPort || !selectedPort.readable) return;

    readLoopActive.current = true;
    const reader = selectedPort.readable.getReader();
    readerRef.current = reader;

    const decoder = new TextDecoder();

    try {
      while (true) {
        const { value, done } = await reader.read();
        if (done) break;

        if (value) {
          bufferRef.current += decoder.decode(value, { stream: true });

          if (flushTimeoutRef.current) window.clearTimeout(flushTimeoutRef.current);

          if (bufferRef.current.includes('\n') || bufferRef.current.includes('\r')) {
            const lines = bufferRef.current.split(/\r?\n|\r/);
            bufferRef.current = lines.pop() || ''; 

            for (const line of lines) {
              const trimmed = line.trim();
              if (trimmed) {
                addLog(trimmed, 'in');
              }
            }
          }

          flushTimeoutRef.current = window.setTimeout(() => {
            flushBuffer();
          }, 200);
        }
      }
    } catch (err: any) {
      if (err.name === 'NetworkError' || err.message?.toLowerCase().includes('device has been lost')) {
        disconnect(true);
      } else if (err.name !== 'AbortError') {
        addLog(`Serial Error: ${err.message}`, 'error');
      }
    } finally {
      try {
        if (reader) {
          reader.releaseLock();
        }
      } catch (e) {}
      readerRef.current = null;
      readLoopActive.current = false;
    }
  }, [addLog, flushBuffer, disconnect]);

  const connect = useCallback(async (options: SerialOptions, existingPort?: any) => {
    if (!('serial' in navigator)) {
      setError('Web Serial API is not supported.');
      return;
    }

    try {
      // Prevent overlapping connection attempts
      if (portRef.current) await disconnect();

      setError(null);
      setStatus('connecting');

      const selectedPort = existingPort || await (navigator as any).serial.requestPort();
      await selectedPort.open({ baudRate: options.baudRate });

      localStorage.setItem('last_baud_rate', options.baudRate.toString());
      portRef.current = selectedPort;
      setStatus('connected');
      addLog(`Online: ${options.baudRate} baud.`, 'info');

      startReading(selectedPort);
    } catch (err: any) {
      // Ignore user cancellation
      if (err.name === 'NotFoundError') {
        setStatus('disconnected');
        return;
      }
      setError(err.message || 'Connection failed.');
      setStatus('disconnected');
    }
  }, [addLog, startReading, disconnect]);

  // Handle Auto-Reconnection on mount
  useEffect(() => {
    const tryAutoConnect = async () => {
      if (!('serial' in navigator) || isAutoConnecting.current) return;

      try {
        isAutoConnecting.current = true;
        const ports = await (navigator as any).serial.getPorts();

        // If we have authorized ports, try to reconnect to the most likely one (the first)
        if (ports.length > 0) {
          const savedBaud = localStorage.getItem('last_baud_rate');
          const baudRate = savedBaud ? parseInt(savedBaud) : 9600;

          // Connect using the existing port reference found in the authorized list
          await connect({ baudRate }, ports[0]);
        }
      } catch (e) {
        console.warn("Auto-reconnection failed or was ignored:", e);
      } finally {
        isAutoConnecting.current = false;
      }
    };

    tryAutoConnect();
    // Only run once on mount
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    const handleDisconnect = (event: any) => {
      if (portRef.current && event.port === portRef.current) {
        disconnect(true);
      }
    };

    if ('serial' in navigator) {
      (navigator as any).serial.addEventListener('disconnect', handleDisconnect);
    }

    return () => {
      if ('serial' in navigator) {
        (navigator as any).serial.removeEventListener('disconnect', handleDisconnect);
      }
    };
  }, [disconnect]);

  return { status, logs, connect, disconnect: () => disconnect(false), error };
};

import React, { useState, useEffect, useRef } from 'react';
