interface KioskModeProps {
  onExit: () => void;
  lastScanResult: ScanResult | null;
  unknownTag: string | null;
  settings: TimeSlotSettings;
}

const KioskMode: React.FC<KioskModeProps> = ({ onExit, lastScanResult, unknownTag, settings }) => {
  const [currentTime, setCurrentTime] = useState(new Date());
  const lastSpokenRef = useRef<string | null>(null);

  useEffect(() => {
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  // Text-to-Speech Logic
  useEffect(() => {
    if (lastScanResult) {
      // Prevent repeating the same scan if the component re-renders
      const scanId = `${lastScanResult.learner.id}-${lastScanResult.time}`;
      if (lastSpokenRef.current === scanId) return;
      lastSpokenRef.current = scanId;

      window.speechSynthesis.cancel();
      const firstName = lastScanResult.learner.firstName || 'Student';
      const message = lastScanResult.isDuplicate 
        ? `${firstName}, already logged.` 
        : `Welcome, ${firstName}.`;

      const utterance = new SpeechSynthesisUtterance(message);
      utterance.rate = 0.9; // Slightly slower for clarity
      utterance.pitch = 1.0;
      window.speechSynthesis.speak(utterance);
    } else if (unknownTag) {
      if (lastSpokenRef.current === unknownTag) return;
      lastSpokenRef.current = unknownTag;

      window.speechSynthesis.cancel();
      const utterance = new SpeechSynthesisUtterance("Access restricted. Unknown card.");
      window.speechSynthesis.speak(utterance);
    } else {
      lastSpokenRef.current = null;
