const extractUid = (text: string): string | null => {
  const clean = text.trim().toUpperCase();
  if (clean.includes('READY') || clean.includes('INITIALIZING') || clean.includes('MFRC522')) return null;
  const hexPattern = /[0-9A-F]{2}(?:[\s:-]?[0-9A-F]{2}){3,9}/;
  const match = clean.match(hexPattern);
  if (match) return match[0].replace(/[\s:-]+/g, '');
  return null;
};

const determineAttendanceType = (now: Date, settings: TimeSlotSettings): AttendanceType => {
  const time = now.getHours().toString().padStart(2, '0') + ':' + now.getMinutes().toString().padStart(2, '0');

  if (time >= settings.amIn.start && time <= settings.amIn.end) return 'AM_IN';
  if (time >= settings.amOut.start && time <= settings.amOut.end) return 'AM_OUT';
  if (time >= settings.pmIn.start && time <= settings.pmIn.end) return 'PM_IN';
  if (time >= settings.pmOut.start && time <= settings.pmOut.end) return 'PM_OUT';

  return 'UNSCHEDULED';
};

const App: React.FC = () => {
  const { status, logs, connect, disconnect } = useSerial();
  const { learners, isLoading, isSyncing, fetchedCount, getFiltered } = useLearners();
  const { uidMappings, adminUids, attendanceLogs, addMapping, toggleAdmin, logAttendance } = useAttendance();
  const { settings, updateSettings } = useSettings();

  const [currentView, setCurrentView] = useState<'registrar' | 'attendance' | 'settings'>('registrar');
  const [isStandbyMode, setIsStandbyMode] = useState(false);

  const [baudRate, setBaudRate] = useState(() => {
    const saved = localStorage.getItem('last_baud_rate');
    return saved ? parseInt(saved) : 9600;
  });
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedLearnerId, setSelectedLearnerId] = useState<string | null>(null);
  const [activeRfid, setActiveRfid] = useState('');
  const [conflictWarning, setConflictWarning] = useState<string | null>(null);
  const [scanFlash, setScanFlash] = useState(false);

  const [lastScanResult, setLastScanResult] = useState<ScanResult | null>(null);
  const [unknownTag, setUnknownTag] = useState<string | null>(null);

  const lastProcessedId = useRef<string | null>(null);

  const speak = (text: string) => {
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'en-US';
    utterance.rate = 0.9;
    window.speechSynthesis.speak(utterance);
  };

  useEffect(() => {
    if (logs.length === 0) return;

    const lastLog = logs[logs.length - 1];
    if (!lastLog || lastLog.type !== 'in' || lastLog.id === lastProcessedId.current) return;

    const scannedUid = extractUid(lastLog.text);
    if (!scannedUid) return;

    lastProcessedId.current = lastLog.id;

    // MASTER KEY LOGIC
    if (adminUids.includes(scannedUid)) {
      setScanFlash(true);
      setTimeout(() => setScanFlash(false), 300);

      const entering = !isStandbyMode;
      setIsStandbyMode(entering);

      if (entering) {
        speak("Master key authorized. Entering Kiosk mode.");
      } else {
        speak("Master key authorized. System unlocked.");
      }
      return;
    }

    if (isStandbyMode) {
      const learner = learners.find(l => {
        const dbUid = l.rfid?.toUpperCase().replace(/[\s:-]+/g, '');
        const localUid = uidMappings[l.id]?.toUpperCase().replace(/[\s:-]+/g, '');
        return dbUid === scannedUid || localUid === scannedUid;
      });

      if (learner) {
        const now = new Date();
        const type = determineAttendanceType(now, settings);

        const todayStr = now.toDateString();
        const isDuplicate = attendanceLogs.some(log => {
          const logDate = new Date(log.timestamp).toDateString();
          return log.learnerId === learner.id && log.type === type && logDate === todayStr;
        });

        if (isDuplicate) {
          setLastScanResult({
            learner, 
            type, 
            uid: scannedUid,
            isDuplicate: true,
            time: now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
          });
        } else {
          logAttendance(learner.id, type);
          setLastScanResult({
            learner, 
            type, 
            uid: scannedUid,
            isDuplicate: false,
            time: now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
          });
        }
        setUnknownTag(null);
      } else {
        setUnknownTag(scannedUid);
        setLastScanResult(null);
      }
    } else {
      setScanFlash(true);
      setActiveRfid(scannedUid);
      setConflictWarning(null);

      const owner = learners.find(l => {
        const dbUid = l.rfid?.toUpperCase().replace(/[\s:-]+/g, '');
        const localUid = uidMappings[l.id]?.toUpperCase().replace(/[\s:-]+/g, '');
        return dbUid === scannedUid || localUid === scannedUid;
      });

      if (owner) {
        setConflictWarning(`Tag assigned to: ${owner.lastName}, ${owner.firstName}`);
      }
      setTimeout(() => setScanFlash(false), 500);
    }
  }, [logs, isStandbyMode, uidMappings, adminUids, learners, settings, logAttendance, attendanceLogs]);

  useEffect(() => {
    if (lastScanResult || unknownTag) {
      const t = setTimeout(() => { 
        setLastScanResult(null); 
        setUnknownTag(null); 
      }, 5000);
      return () => clearTimeout(t);
    }
  }, [lastScanResult, unknownTag]);

  const handleSaveMapping = () => {
    if (!selectedLearnerId || !activeRfid || conflictWarning) return;
    addMapping(selectedLearnerId, activeRfid);
    setActiveRfid('');
    setSelectedLearnerId(null);
    setConflictWarning(null);
    setScanFlash(true);
    setTimeout(() => setScanFlash(false), 400);
  };

  const filteredLearners = useMemo(() => 
    getFiltered(searchQuery, uidMappings), 
    [searchQuery, learners, uidMappings, getFiltered]
  );

  const selectedLearner = learners.find(l => l.id === selectedLearnerId) || null;

  if (isStandbyMode) {
    return (
      <KioskMode 
        onExit={() => setIsStandbyMode(false)} 
        lastScanResult={lastScanResult} 
        unknownTag={unknownTag} 
        settings={settings}
      />
    );
  }

  return (
    <div className="min-h-screen bg-app-bg text-on-surface flex flex-col font-sans selection:bg-primary-container selection:text-on-primary-container">
      <div className="flex-grow max-w-7xl mx-auto w-full px-4 lg:px-8 py-8 space-y-8">
        <Header 
          status={status} 
          baudRate={baudRate} 
          currentView={currentView}
          onViewChange={setCurrentView}
          onBaudRateChange={(b) => {
            setBaudRate(b);
            localStorage.setItem('last_baud_rate', b.toString());
          }} 
          onConnect={() => connect({ baudRate })} 
          onDisconnect={disconnect} 
          onEnterKiosk={() => setIsStandbyMode(true)} 
        />

        <main className="animate-in fade-in duration-700">
          {currentView === 'registrar' && (
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
              <div className="lg:col-span-4 space-y-6">
                <PairingConsole 
                  activeRfid={activeRfid} 
                  selectedLearner={selectedLearner} 
                  conflictWarning={conflictWarning} 
                  scanFlash={scanFlash} 
                  onSave={handleSaveMapping}
                  isAdmin={adminUids.includes(activeRfid)}
                  onToggleAdmin={() => toggleAdmin(activeRfid)}
                />

                <section className="bg-surface rounded-m3-xl p-6 shadow-sm border border-black/5">
                  <div className="flex justify-between items-center mb-4">
                    <h2 className="text-[11px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2">
                      <span className="material-symbols-outlined text-sm">terminal</span>
                      Serial Monitor
                    </h2>
                    <span className={`text-[9px] font-black px-2 py-0.5 rounded ${status === 'connected' ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-100 text-slate-400'}`}>
                      {status.toUpperCase()}
                    </span>
                  </div>
                  <div className="h-64 rounded-m3-lg overflow-hidden bg-surface-variant border border-black/5">
                    <Terminal logs={logs.slice(-100)} />
                  </div>
                </section>
              </div>
              <div className="lg:col-span-8 space-y-6">
                <div className="relative">
                  <span className="material-symbols-outlined absolute left-5 top-1/2 -translate-y-1/2 text-slate-400">search</span>
                  <input 
                    type="text" 
                    placeholder="Search registry..." 
                    value={searchQuery} 
                    onChange={e => setSearchQuery(e.target.value)} 
                    className="w-full bg-surface border border-black/5 rounded-full pl-14 pr-6 py-4 text-base focus:ring-2 focus:ring-primary/20 outline-none transition-all placeholder:text-slate-300 shadow-sm" 
                  />
                </div>
                <LearnerDirectory 
                  learners={filteredLearners} 
                  uidMappings={uidMappings} 
                  selectedId={selectedLearnerId} 
                  onSelect={setSelectedLearnerId} 
                  isLoading={isLoading} 
                  isSearching={searchQuery.trim().length > 0}
                  isSyncing={isSyncing} 
                  fetchedCount={fetchedCount} 
                />
              </div>
            </div>
          )}

          {currentView === 'attendance' && (
            <AttendanceLogs logs={attendanceLogs} learners={learners} />
          )}

          {currentView === 'settings' && (
            <Settings settings={settings} onUpdate={updateSettings} />
          )}
        </main>
      </div>

      <Footer 
        status={status} 
        baudRate={baudRate} 
        assignedCount={Object.keys(uidMappings).length} 
        totalCount={learners.length} 
      />
    </div>
  );
};

export default App;

import React from 'react';
import { Learner } from '../types';

interface PairingConsoleProps {
  activeRfid: string;
  selectedLearner: Learner | null;
  conflictWarning: string | null;
  scanFlash: boolean;
  onSave: () => void;
  isAdmin?: boolean;
  onToggleAdmin?: () => void;
}

const PairingConsole: React.FC<PairingConsoleProps> = ({
  activeRfid, selectedLearner, conflictWarning, scanFlash, onSave, isAdmin, onToggleAdmin
}) => {
  return (
    <section className="bg-white rounded-m3-xl p-8 shadow-sm border border-black/5 relative overflow-hidden">
      <div className="absolute top-0 right-0 p-6 opacity-[0.03] pointer-events-none">
        <span className="material-symbols-outlined text-9xl">link</span>
      </div>

      <h2 className="text-[11px] font-black text-primary uppercase tracking-[0.4em] mb-10 flex items-center gap-3">
        <span className="material-symbols-outlined text-xl">sync_alt</span>
        Pairing Unit
      </h2>

      <div className="space-y-10">
        <div className="space-y-4">
          <div className="flex justify-between items-end px-1">
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Sensor Status</label>
            {activeRfid && (
              <button 
                onClick={onToggleAdmin}
                className={`text-[9px] font-black uppercase tracking-widest px-3 py-1 rounded-full border transition-all ${
                  isAdmin 
                  ? 'bg-amber-100 border-amber-200 text-amber-700' 
                  : 'bg-slate-50 border-black/5 text-slate-400 hover:text-primary hover:border-primary/20'
                }`}
              >
                {isAdmin ? '★ Master Key Active' : 'Set as Master Key'}
              </button>
            )}
          </div>

          <div 
            className={`p-8 rounded-3xl border-2 transition-all duration-300 ${scanFlash ? 'scale-[1.03] bg-primary/5' : 'bg-slate-50'} ${
              activeRfid 
              ? (conflictWarning ? 'border-accent/20 bg-accent/5' : 'border-primary/20 bg-white shadow-lg shadow-primary/5') 
              : 'border-black/5'
            }`}
          >
            {activeRfid ? (
              <div className="flex items-center gap-5">
                <div className={`w-12 h-12 rounded-2xl flex items-center justify-center ${
                  conflictWarning 
                  ? 'bg-accent text-white shadow-lg shadow-accent/20' 
                  : (isAdmin ? 'bg-amber-500 text-white shadow-lg shadow-amber-200' : 'bg-primary text-white shadow-lg shadow-primary/20')
                }`}>
                  <span className="material-symbols-outlined">{conflictWarning ? 'error' : (isAdmin ? 'key' : 'nfc')}</span>
                </div>
                <div>
                  <div className={`text-[11px] font-black tracking-widest uppercase ${conflictWarning ? 'text-accent' : (isAdmin ? 'text-amber-600' : 'text-primary')}`}>
                    {conflictWarning ? 'UID Reserved' : (isAdmin ? 'Master Key' : 'RFID Active')}
                  </div>
                  <code className="text-2xl font-black text-primary font-mono tracking-tighter">{activeRfid}</code>
                </div>
              </div>
            ) : (
              <div className="text-center py-4 flex flex-col items-center gap-3">
                <span className="material-symbols-outlined text-slate-200 text-5xl animate-pulse">contactless</span>
                <p className="text-[11px] font-black text-slate-300 tracking-[0.3em] uppercase">Tap Tag to Begin</p>
              </div>
            )}
          </div>
          {conflictWarning && (
            <p className="text-[10px] font-black text-accent px-2 flex items-center gap-2 animate-pulse uppercase">
              <span className="material-symbols-outlined text-sm">priority_high</span>
              {conflictWarning}
            </p>
          )}
        </div>

        <div className="space-y-4">
          <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Assignment Target</label>
          <div className={`p-8 rounded-3xl border-2 transition-all duration-300 ${selectedLearner ? 'bg-white border-primary/20 shadow-lg shadow-primary/5' : 'bg-slate-50 border-black/5 border-dashed'}`}>
            {selectedLearner ? (
              <div className="flex items-center gap-5">
                <div className="w-14 h-14 bg-primary text-white rounded-2xl flex items-center justify-center font-black text-xl shadow-lg shadow-primary/20 uppercase italic flex-shrink-0">
                  {selectedLearner.lastName?.charAt(0)}
                </div>
                <div className="overflow-hidden">
                  <div className="font-black text-primary text-lg leading-tight uppercase italic truncate">
                    {selectedLearner.lastName}, {selectedLearner.firstName}
                  </div>
                  <div className="flex flex-col gap-0.5 mt-1">
                    <div className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">LRN: {selectedLearner.lrn || 'INTERNAL'}</div>
                    <div className="text-[9px] text-primary/40 font-black uppercase tracking-widest truncate">
                      {selectedLearner.grade_level} • {selectedLearner.section_name}
                    </div>
                  </div>
                </div>
              </div>
            ) : (
              <div className="text-center py-4 flex flex-col items-center gap-3">
                <span className="material-symbols-outlined text-slate-200 text-5xl">person_search</span>
                <p className="text-[11px] font-black text-slate-300 tracking-[0.3em] uppercase">Select Student</p>
              </div>
            )}
          </div>
        </div>

        <button
          disabled={!activeRfid || !selectedLearner || !!conflictWarning}
          onClick={onSave}
          className="w-full bg-primary disabled:opacity-10 text-white font-black py-5 rounded-full shadow-[0_12px_24px_-8px_rgba(1,14,91,0.4)] hover:shadow-xl active:scale-95 transition-all flex items-center justify-center gap-4 text-[12px] tracking-[0.4em] uppercase"
        >
          <span className="material-symbols-outlined text-xl">link</span>
          Complete Link
        </button>
      </div>
    </section>
  );
};

export default PairingConsole;
